namespace AgriTech.Api.Models;

/// <summary>
/// Cached agronomic advisory generated by an LLM (e.g. Gemini) for a canonical
/// plant-ml crop/disease key (e.g. "tomato/late_blight").
/// </summary>
public class DiseaseAdvisory
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string ClassKey { get; set; } = string.Empty;
    public string Crop { get; set; } = string.Empty;
    public string Condition { get; set; } = string.Empty;
    public string? ScientificName { get; set; }
    public string Severity { get; set; } = string.Empty;
    public string ImmediateAction { get; set; } = string.Empty;
    public string RecommendedTreatmentsJson { get; set; } = "[]";
    public string MicroclimateRisk { get; set; } = string.Empty;
    public string LlmModel { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
}
